import{_ as e,c as i,o as a,aM as t}from"./chunks/framework.ArsEi8Co.js";const n="/docs/imgs/linux-tee.svg",g=JSON.parse('{"title":"tee：终端里的\\"三通管\\"","description":"","frontmatter":{"title":"tee：终端里的\\"三通管\\"","date":"2026-08-22T00:00:00.000Z","permalink":"/service/tee","tags":["Linux"],"categories":["Linux"],"name":"tee：终端里的\\"三通管\\""},"headers":[],"relativePath":"service/tee.md","filePath":"02.服务端/03.tee.md","lastUpdated":1787716250000}'),l={name:"service/tee.md"};function p(d,s,h,r,o,k){return a(),i("div",null,s[0]||(s[0]=[t('<h1 id="tee-终端里的-三通管" tabindex="-1">tee：终端里的&quot;三通管&quot; <a class="header-anchor" href="#tee-终端里的-三通管" aria-label="Permalink to &quot;tee：终端里的&quot;三通管&quot;&quot;">​</a></h1><h2 id="文章导览" tabindex="-1">文章导览 <a class="header-anchor" href="#文章导览" aria-label="Permalink to &quot;文章导览&quot;">​</a></h2><p align="center"><img src="'+n+`" alt="文章导览"></p><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>最近在调试 LLM 应用时，我遇到了一个特别影响效率的问题：</p><p>程序一跑起来，终端日志就像瀑布一样疯狂滚动。等我想找刚才的报错堆栈时，关键信息早已被顶出屏幕，往上翻半天也找不到。</p><p>给项目接入正规的日志模块当然更完善，但在快速验证想法、跑 Demo 的阶段，为了保存一次输出就去改代码，未免有些麻烦。</p><p>好消息是，这种情况不用改代码，一个 Linux、macOS 等系统自带的命令就能帮上忙：<strong>tee</strong>。</p><p>它可以把同一份输出一边显示在终端，一边保存到文件。通常不影响终端观察，也方便运行结束后搜索和回看。</p><h2 id="一条命令-边看边存" tabindex="-1">一条命令，边看边存 <a class="header-anchor" href="#一条命令-边看边存" aria-label="Permalink to &quot;一条命令，边看边存&quot;">​</a></h2><p>以 npm 脚本为例：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tmp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --silent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo:04</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;这个项目有哪些文件？&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tmp/demo.log</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>核心就是第二行。日志会照常显示在终端，同时悄悄写入 <code>./tmp/demo.log</code>。等程序跑完，再打开文件慢慢找报错，不用和滚动的屏幕“赛跑”了。</p><p>其中：</p><ul><li><code>2&gt;&amp;1</code>：把错误输出合并到正常输出，避免漏掉报错；</li><li><code>|</code>：把合并后的输出交给下一个命令；</li><li><code>tee ./tmp/demo.log</code>：在终端显示输出，同时保存到文件；</li><li><code>--silent</code>：减少 npm 自身的提示信息，可按需省略。</li></ul><p>有个小提醒：<code>tee</code> 不会自动创建上级目录，所以示例先用 <code>mkdir -p ./tmp</code> 把目录准备好。</p><h2 id="tee-终端里的-三通管-1" tabindex="-1"><code>tee</code>：终端里的“三通管” <a class="header-anchor" href="#tee-终端里的-三通管-1" aria-label="Permalink to &quot;\`tee\`：终端里的“三通管”&quot;">​</a></h2><p><code>tee</code> 这个名字来自水管中的“三通管”（T 形管件）。它会接收标准输入，然后把内容分成两路：</p><ul><li>一路继续输出到终端；</li><li>一路写入指定文件。</li></ul><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>命令输出 ──► tee ──► 终端显示</span></span>
<span class="line"><span>                 └──► 写入文件</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>先来看一个最简单的例子：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;hello llm&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tmp/debug.log</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>终端会显示 <code>hello llm</code>，文件中也会保存同样的内容。</p><h2 id="关键一步-别漏掉错误日志" tabindex="-1">关键一步：别漏掉错误日志 <a class="header-anchor" href="#关键一步-别漏掉错误日志" aria-label="Permalink to &quot;关键一步：别漏掉错误日志&quot;">​</a></h2><p>每个命令运行时，默认都有三个标准数据流：</p><table tabindex="0"><thead><tr><th style="text-align:center;">编号</th><th style="text-align:left;">名称</th><th style="text-align:left;">缩写</th><th style="text-align:left;">作用</th></tr></thead><tbody><tr><td style="text-align:center;"><code>0</code></td><td style="text-align:left;">标准输入</td><td style="text-align:left;"><code>stdin</code></td><td style="text-align:left;">接收键盘或其他命令传来的输入</td></tr><tr><td style="text-align:center;"><code>1</code></td><td style="text-align:left;">标准输出</td><td style="text-align:left;"><code>stdout</code></td><td style="text-align:left;">输出正常结果</td></tr><tr><td style="text-align:center;"><code>2</code></td><td style="text-align:left;">标准错误</td><td style="text-align:left;"><code>stderr</code></td><td style="text-align:left;">输出错误和警告</td></tr></tbody></table><p>终端默认会同时显示 <code>stdout</code> 和 <code>stderr</code>，所以平时看起来没什么区别。可实际上，它们走的是两条不同的通道。</p><p>坑就在这里：管道 <code>|</code> 默认只把 <code>stdout</code> 交给下一个命令。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tmp/demo.log</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>如果程序同时产生正常输出和报错，<code>tee</code> 只能收到正常输出。报错仍会显示在终端，却不会写进日志文件。</p><p>所以，调试时更推荐这样写：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tmp/demo.log</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>第一次看到 <code>2&gt;&amp;1</code>，是不是有点像乱码？别担心，拆开看就简单了：</p><ul><li><code>2</code> 代表 <code>stderr</code>；</li><li><code>&amp;1</code> 代表 <code>stdout</code> 当前指向的位置。</li></ul><p>合起来就是：<strong>让 <code>stderr</code> 和 <code>stdout</code> 走同一条通道</strong>。这样再接管道，正常信息和报错就都能进入 <code>tee</code>。</p><p>这里的 <code>&amp;</code> 很重要：它表示后面的 <code>1</code> 是文件描述符编号，而不是文件名。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 把 stderr 合并到 stdout</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">command</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 把 stderr 写进一个名为“1”的文件，并不是同一回事</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">command</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>不想记文件描述符也没关系，只要记住一句话：<strong><code>2&gt;&amp;1</code> 就是把错误输出并入正常输出。</strong></p><h2 id="三个顺手又实用的小技巧" tabindex="-1">三个顺手又实用的小技巧 <a class="header-anchor" href="#三个顺手又实用的小技巧" aria-label="Permalink to &quot;三个顺手又实用的小技巧&quot;">​</a></h2><h3 id="追加写入-保留历史日志" tabindex="-1">追加写入，保留历史日志 <a class="header-anchor" href="#追加写入-保留历史日志" aria-label="Permalink to &quot;追加写入，保留历史日志&quot;">​</a></h3><p><code>tee</code> 默认会覆盖同名文件。如果想保留之前的日志，增加 <code>-a</code>：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tee</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tmp/demo.log</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="文件名加时间-方便回溯" tabindex="-1">文件名加时间，方便回溯 <a class="header-anchor" href="#文件名加时间-方便回溯" aria-label="Permalink to &quot;文件名加时间，方便回溯&quot;">​</a></h3><p>调试不同版本时，可以把时间写进文件名：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;./tmp/demo-$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%Y%m%d-%H%M%S).log&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>运行后会得到类似 <code>demo-20260823-143022.log</code> 的文件，方便对比和回溯。</p><h3 id="文件存完整-屏幕看重点" tabindex="-1">文件存完整，屏幕看重点 <a class="header-anchor" href="#文件存完整-屏幕看重点" aria-label="Permalink to &quot;文件存完整，屏幕看重点&quot;">​</a></h3><p><code>tee</code> 会继续把内容传给后面的命令，因此可以一边保存完整日志，一边筛选终端显示内容：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tmp/demo.log</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;报错|工具调用&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>如果没有安装 <code>rg</code>，也可以使用 <code>grep</code>：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tmp/demo.log</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;报错|工具调用&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>注意：这里过滤的只是终端最终显示的内容，<code>demo.log</code> 中仍然保留完整日志。</p><h2 id="只保存需要的输出" tabindex="-1">只保存需要的输出 <a class="header-anchor" href="#只保存需要的输出" aria-label="Permalink to &quot;只保存需要的输出&quot;">​</a></h2><p>大多数时候，<code>stdout</code> 和 <code>stderr</code> 一起保存最省心。但如果正常输出特别长，或者某些警告实在太吵，也可以只留其中一种。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 只保存 stdout，丢弃 stderr</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tmp/demo.log</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 只保存 stderr，丢弃 stdout</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 1&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tmp/demo.log</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>这里出现了一个新面孔：<code>/dev/null</code>。它是 Linux、macOS 等 Unix 系统中的特殊设备文件，可以把它理解成一个“黑洞”：<strong>任何写进去的内容都会被直接丢弃，不会显示，也不会保存。</strong></p><p>所以上面两条命令分别表示：</p><ul><li><code>2&gt;/dev/null</code>：丢弃 <code>stderr</code>，只让 <code>stdout</code> 进入 <code>tee</code>；</li><li><code>2&gt;&amp;1 1&gt;/dev/null</code>：先让 <code>stderr</code> 指向原本的 <code>stdout</code> 通道，再把 <code>stdout</code> 改到 <code>/dev/null</code>，最终只有 <code>stderr</code> 进入 <code>tee</code>。</li></ul><p>重定向会从左到右执行，因此第二条命令的顺序不能颠倒。看到这里觉得有点绕也很正常——如果暂时不需要区分两种输出，记住最常用的 <code>2&gt;&amp;1 | tee</code> 就够用了。</p><h2 id="使用前要留意的三个细节" tabindex="-1">使用前要留意的三个细节 <a class="header-anchor" href="#使用前要留意的三个细节" aria-label="Permalink to &quot;使用前要留意的三个细节&quot;">​</a></h2><p>如果只是日常调试，前面的用法已经够用；下面三个细节主要面向脚本和自动化场景。</p><h3 id="日志为什么不实时了" tabindex="-1">日志为什么不实时了？ <a class="header-anchor" href="#日志为什么不实时了" aria-label="Permalink to &quot;日志为什么不实时了？&quot;">​</a></h3><p>用了管道后，有些程序的日志会变慢，甚至攒一批后才一起出现。</p><p>这通常不是 <code>tee</code> 在故意拖延，而是上游程序或它使用的运行库发现 <code>stdout</code> 不再直接连接终端，于是改变了缓冲策略。Linux、macOS 等系统都可能遇到这种情况。</p><p>如果程序支持关闭缓冲或强制刷新，优先使用它自身提供的选项。在 Linux 上，也可以视情况尝试：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">stdbuf</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -oL</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -eL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> command</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tmp/demo.log</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>如果程序必须在真实终端环境中才会及时输出，还可以用 <code>script</code> 模拟终端。不过 macOS 和 Linux 的参数不同：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># macOS 常见写法</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">script</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tmp/demo.log</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> command</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux（util-linux）常见写法</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">script</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;command&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tmp/demo.log</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><code>script</code> 记录的是终端会话，日志里可能带有颜色控制符、终端信息或头尾记录，因此它更适合作为缓冲问题的备选方案，而不是所有场景下都替代 <code>tee</code>。</p><h3 id="命令失败-状态却是成功" tabindex="-1">命令失败，状态却是成功？ <a class="header-anchor" href="#命令失败-状态却是成功" aria-label="Permalink to &quot;命令失败，状态却是成功？&quot;">​</a></h3><p>执行下面的命令时：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">command</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tmp/demo.log</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Shell 默认关注管道中最后一个命令，也就是 <code>tee</code> 的退出状态。即使前面的 <code>command</code> 失败，只要 <code>tee</code>正常结束，整条命令仍可能表现为成功。平时手动调试不一定会注意到它，但放进自动化脚本或 CI，就很容易造成误判。</p><p>Bash 和 Zsh 可以提前启用 <code>pipefail</code>：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pipefail</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">command</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tmp/demo.log</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>这样，只要管道中的任意命令失败，整条管道就会返回非零状态。</p><h3 id="日志里的奇怪字符是什么" tabindex="-1">日志里的奇怪字符是什么？ <a class="header-anchor" href="#日志里的奇怪字符是什么" aria-label="Permalink to &quot;日志里的奇怪字符是什么？&quot;">​</a></h3><p>一些命令会输出 ANSI 颜色代码。保存后直接打开日志，可能看到类似 <code>^[</code> 的字符。可以优先关闭上游命令的彩色输出；具体参数因工具而异，常见形式包括 <code>--no-color</code>。</p><p>另外，如果进程被 <code>kill -9</code> 强制终止，上游程序尚未刷新的少量日志仍可能丢失。</p><h2 id="windows-平台怎么用" tabindex="-1">Windows 平台怎么用 <a class="header-anchor" href="#windows-平台怎么用" aria-label="Permalink to &quot;Windows 平台怎么用&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">环境</th><th style="text-align:left;">使用方式</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">Linux / macOS / Unix</td><td style="text-align:left;"><code>tee</code></td><td style="text-align:left;">通常开箱即用</td></tr><tr><td style="text-align:left;">Windows PowerShell</td><td style="text-align:left;"><code>Tee-Object</code></td><td style="text-align:left;">PowerShell 内置的等价命令</td></tr><tr><td style="text-align:left;">Windows Git Bash / WSL</td><td style="text-align:left;"><code>tee</code></td><td style="text-align:left;">可以直接使用 Unix 写法</td></tr><tr><td style="text-align:left;">极简容器镜像</td><td style="text-align:left;">视镜像而定</td><td style="text-align:left;"><code>scratch</code> 等镜像可能不包含该命令</td></tr></tbody></table><p>PowerShell 示例：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">npm run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">silent demo:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">04</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;...&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Tee-Object</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FilePath C:\\temp\\demo.log</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>需要注意，PowerShell 的流和重定向规则与 POSIX Shell 并不完全相同。上面的写法适合日常记录输出；复杂脚本应按所用 PowerShell 版本进一步确认。</p><h2 id="一张表快速记住-tee" tabindex="-1">一张表快速记住 <code>tee</code> <a class="header-anchor" href="#一张表快速记住-tee" aria-label="Permalink to &quot;一张表快速记住 \`tee\`&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">需求</th><th style="text-align:left;">命令</th></tr></thead><tbody><tr><td style="text-align:left;">边看边保存 stdout</td><td style="text-align:left;"><code>command | tee output.log</code></td></tr><tr><td style="text-align:left;">同时保存正常输出和报错</td><td style="text-align:left;"><code>command 2&gt;&amp;1 | tee output.log</code></td></tr><tr><td style="text-align:left;">追加到已有日志</td><td style="text-align:left;"><code>command 2&gt;&amp;1 | tee -a output.log</code></td></tr><tr><td style="text-align:left;">只保存 stdout</td><td style="text-align:left;"><code>command 2&gt;/dev/null | tee output.log</code></td></tr><tr><td style="text-align:left;">只保存 stderr</td><td style="text-align:left;"><code>command 2&gt;&amp;1 1&gt;/dev/null | tee output.log</code></td></tr><tr><td style="text-align:left;">保存完整日志、终端只看重点</td><td style="text-align:left;"><code>command 2&gt;&amp;1 | tee output.log | rg &quot;关键词&quot;</code></td></tr></tbody></table><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>调试 LLM 应用时，日志就是定位问题的线索。</p><p>下次再遇到终端刷屏，先别急着和鼠标滚轮较劲。试着在命令后面加上：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tmp/debug.log</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>让终端负责实时显示，让日志文件负责完整记录。等程序跑完，再用编辑器或 <code>rg</code> 慢慢搜索。</p><p>一个小小的 <code>tee</code>，不会替代正规的日志系统，却很适合那些“先跑起来看看”的时刻。少翻几次屏幕，多留一份线索，调试也能从容不少。</p>`,92)]))}const u=e(l,[["render",p]]);export{g as __pageData,u as default};
